import re, configparser, subprocess, json, os, sys
cfg=os.path.expanduser("~/.config/gpsconfig/stations.cfg")
txt=open(cfg, encoding="latin-1", errors="replace").read()
# split into sections
secs={}
cur=None
for ln in txt.splitlines():
    m=re.match(r"^\[([^\]]+)\]\s*$", ln)
    if m: cur=m.group(1); secs[cur]=[]; continue
    if cur is not None: secs[cur].append(ln)
stats={}
for name, lines in secs.items():
    st=None
    for ln in lines:
        m=re.match(r"^\s*station_status\s*=\s*(\S+)", ln)
        if m: st=m.group(1)
    if st: stats[name]=st
print("stations with station_status set:", len(stats))
for k,v in sorted(stats.items(), key=lambda x:x[1]): print(f"   {k} = {v}")
EOF

